turns.content:
{"t":"say","text":"I'll draw a private RAG assistant for employees, using Model Studio Qwen models, a vector store and your docs in OSS."}
{"t":"plan","products":["users","alb","ecs","model-studio","milvus","oss","nat"]}
{"t":"assume","id":"new-build","text":"New build hosted on Alibaba Cloud","alt":"Deployed on existing on-premises servers"}
{"t":"assume","id":"scale","text":"Hundreds of internal employees","alt":"Thousands of employees across regions"}
{"t":"group","id":"internal","kind":"external","label":"Corporate network","parent":null}
{"t":"node","id":"users","product":"users","label":"Employees","group":"internal","why":"Internal staff asking policy and wiki questions."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Assistant VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"Internal ALB","group":"vpc","zones":["a","b"],"why":"Private load balancer reachable only from corporate network."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"app","product":"ecs","label":"RAG application","group":"vpc","zones":["a","b"],"why":"Runs the retrieval and Qwen prompt logic."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"node","id":"vector","product":"milvus","label":"Vector store","group":"vpc","zones":["a","b"],"why":"Stores embeddings of policies and wiki pages for retrieval."}
{"t":"edge","id":"e-app-vector","from":"app","to":"vector","label":"search"}
{"t":"node","id":"docs","product":"oss","label":"Policy and wiki docs","group":"sg","why":"Holds source documents to be chunked and embedded."}
{"t":"edge","id":"e-app-docs","from":"app","to":"docs","label":"read"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Gives the app outbound access to call Model Studio APIs."}
{"t":"edge","id":"e-app-nat","from":"app","to":"nat","kind":"control"}
{"t":"node","id":"llm","product":"model-studio","label":"Qwen models","group":"sg","why":"Hosted Qwen API generates answers from retrieved context."}
{"t":"edge","id":"e-nat-llm","from":"nat","to":"llm","label":"API"}
{"t":"ask","id":"doc-ingestion","text":"How will policy and wiki documents be ingested into the vector store?","options":["Manual upload to OSS","Automated sync from existing wiki","Custom ingestion pipeline"]}
{"t":"ask","id":"auth-method","text":"How should employees authenticate to the assistant?","options":["SSO via IDaaS","Existing corporate SSO","No auth for now"]}
{"t":"done","summary":"Internal RAG assistant with ECS, Milvus, OSS and Qwen via Model Studio behind a private ALB."}

{"t":"say","text":"I'll draw a fully serverless REST API using Function Compute and API Gateway, with Tair for caching and Tablestore for data."}
{"t":"req","text":"Serverless and pay-per-use only"}
{"t":"plan","products":["mobile-app","httpdns","esa","cloud-native-api-gateway","fc","tair","tablestore","oss","sls"]}
{"t":"assume","id":"region","text":"Singapore (ap-southeast-1)","alt":"Another region"}
{"t":"assume","id":"auth","text":"API keys or JWT via gateway","alt":"Custom auth in functions"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"app","product":"mobile-app","label":"Mobile app","group":"internet","why":"Calls the REST API from iOS or Android devices."}
{"t":"node","id":"httpdns","product":"httpdns","label":"HTTPDNS","group":null,"why":"Prevents DNS hijacking for mobile clients."}
{"t":"edge","id":"e-app-httpdns","from":"app","to":"httpdns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Accelerates API calls and absorbs traffic spikes at the edge."}
{"t":"edge","id":"e-app-esa","from":"app","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"API VPC","parent":"sg"}
{"t":"node","id":"gateway","product":"cloud-native-api-gateway","label":"API Gateway","group":"vpc","why":"Routes REST requests, throttles spikes and validates tokens."}
{"t":"edge","id":"e-esa-gateway","from":"esa","to":"gateway","label":"origin"}
{"t":"node","id":"api","product":"fc","label":"API functions","group":"vpc","why":"Runs REST handlers serverlessly; scales to zero when idle."}
{"t":"edge","id":"e-gateway-api","from":"gateway","to":"api","label":"HTTP"}
{"t":"node","id":"cache","product":"tair","label":"Hot data cache","group":"vpc","why":"Caches frequent reads so functions stay fast under spikes."}
{"t":"edge","id":"e-api-cache","from":"api","to":"cache","label":"read/write"}
{"t":"node","id":"db","product":"tablestore","label":"Data store","group":"sg","why":"Serverless NoSQL table that scales automatically with traffic."}
{"t":"edge","id":"e-api-db","from":"api","to":"db","label":"data"}
{"t":"node","id":"files","product":"oss","label":"File storage","group":"sg","why":"Stores user uploads and static assets without compute cost."}
{"t":"edge","id":"e-api-files","from":"api","to":"files","label":"objects"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Collects function logs and metrics for debugging and alerts."}
{"t":"edge","id":"e-api-logs","from":"api","to":"logs","kind":"control"}
{"t":"ask","id":"db-shape","text":"Is your data relational (joins, transactions) or key-value / document style?","options":["Key-value or document","Relational with joins"]}
{"t":"ask","id":"realtime","text":"Does the mobile app need real-time push notifications or WebSockets?","options":["No, REST only","Yes, push or WebSocket"]}
{"t":"done","summary":"Fully serverless REST API on Function Compute behind Cloud-native API Gateway and ESA, with Tair cache, Tablestore and OSS."}

{"t":"say","text":"I'll design a highly available web architecture for your Southeast Asia online store in Singapore, with ESA, ALB, ECS, Tair and RDS."}
{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","rds","oss","sls","nat"]}
{"t":"assume","id":"region","text":"Singapore region for Southeast Asia users","alt":"Jakarta or Kuala Lumpur"}
{"t":"assume","id":"scale","text":"30k daily users with big sales peaks","alt":"Steady traffic without peaks"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Shoppers","group":"internet","why":"Customers browsing the online store."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves store domain to ESA edge."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Caches static assets and accelerates dynamic API calls across Southeast Asia."}
{"t":"edge","id":"e-users-esa","from":"users","to":"esa","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Store VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Distributes traffic across two zones for high availability."}
{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Protects against OWASP attacks and bots during sales peaks."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
{"t":"node","id":"app","product":"ecs","label":"App servers","group":"vpc","zones":["a","b"],"why":"Runs the store backend across two zones."}
{"t":"node","id":"scaling","product":"ess","label":"Auto Scaling","group":"vpc","attachTo":"app","why":"Scales out instances automatically during big sales peaks."}
{"t":"edge","id":"e-alb-app","from":"alb","to":"app"}
{"t":"say","text":"Adding session cache, database, object storage for media, and NAT for outbound access."}
{"t":"node","id":"cache","product":"tair","label":"Session cache","group":"vpc","zones":["a","b"],"why":"Stores sessions and hot product data with zone redundancy."}
{"t":"node","id":"db","product":"rds","label":"Orders DB","group":"vpc","zones":["a","b"],"why":"Primary relational database for orders and inventory with HA standby."}
{"t":"edge","id":"e-app-cache","from":"app","to":"cache"}
{"t":"edge","id":"e-app-db","from":"app","to":"db","label":"SQL"}
{"t":"node","id":"media","product":"oss","label":"Product images","group":"sg","why":"Stores product images and static assets served via ESA."}
{"t":"edge","id":"e-esa-media","from":"esa","to":"media","label":"images"}
{"t":"node","id":"nat","product":"nat","label":"NAT Gateway","group":"vpc","why":"Provides outbound internet for app servers to call payment APIs."}
{"t":"edge","id":"e-app-nat","from":"app","to":"nat","label":"outbound"}
{"t":"node","id":"logs","product":"sls","label":"Logs","group":"sg","why":"Centralizes application logs and metrics for monitoring."}
{"t":"edge","id":"e-app-logs","from":"app","to":"logs","kind":"control"}
{"t":"ask","id":"payment-gateway","text":"Do you need to integrate with external payment gateways or third-party APIs?","options":["Yes, external payments","No, internal only"]}
{"t":"ask","id":"database-engine","text":"Which database engine do you prefer for the orders database?","options":["MySQL","PostgreSQL"]}
{"t":"done","summary":"Highly available e-commerce architecture in Singapore with ESA, ALB, WAF, ECS with Auto Scaling, Tair, RDS, OSS and SLS."}

{"t":"say","text":"I'll draw an ACK-based Kubernetes platform for your 20 Java microservices with MSE Nacos, an API gateway, RocketMQ, Tair and PolarDB."}
{"t":"plan","products":["users","dns","alb","ack","mse","cloud-native-api-gateway","rocketmq","tair","polardb","acr","sls","arms"]}
{"t":"assume","id":"exposure","text":"Public-facing API entry point","alt":"Internal only via VPN"}
{"t":"assume","id":"region","text":"Singapore region","alt":"Another region"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Clients","group":"internet","why":"External callers reaching the microservices platform."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves the API domain to the ALB."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Microservices VPC","parent":"sg"}
{"t":"node","id":"alb","product":"alb","label":"ALB","group":"vpc","zones":["a","b"],"why":"Ingress load balancer spreading traffic across zones."}
{"t":"edge","id":"e-users-alb","from":"users","to":"alb","label":"HTTPS"}
{"t":"node","id":"gateway","product":"cloud-native-api-gateway","label":"API Gateway","group":"vpc","zones":["a","b"],"why":"Single API entry point routing to backend services."}
{"t":"edge","id":"e-alb-gateway","from":"alb","to":"gateway"}
{"t":"node","id":"ack","product":"ack","label":"ACK Cluster","group":"vpc","zones":["a","b"],"why":"Runs the 20 Java microservices on managed Kubernetes."}
{"t":"edge","id":"e-gateway-ack","from":"gateway","to":"ack","label":"routes"}
{"t":"node","id":"mse","product":"mse","label":"MSE Nacos","group":"vpc","zones":["a","b"],"why":"Service discovery and configuration for all microservices."}
{"t":"edge","id":"e-ack-mse","from":"ack","to":"mse","label":"discovery","kind":"control"}
{"t":"node","id":"mq","product":"rocketmq","label":"RocketMQ","group":"vpc","zones":["a","b"],"why":"Async messaging between microservices."}
{"t":"edge","id":"e-ack-mq","from":"ack","to":"mq","label":"events","kind":"async"}
{"t":"node","id":"cache","product":"tair","label":"Tair Cache","group":"vpc","zones":["a","b"],"why":"Shared in-memory cache for fast data access."}
{"t":"edge","id":"e-ack-cache","from":"ack","to":"cache","label":"read/write"}
{"t":"node","id":"db","product":"polardb","label":"PolarDB","group":"vpc","zones":["a","b"],"why":"Relational database with compute-storage separation."}
{"t":"edge","id":"e-ack-db","from":"ack","to":"db","label":"SQL"}
{"t":"say","text":"Adding ACR for container images and observability with ARMS and SLS."}
{"t":"node","id":"acr","product":"acr","label":"Container Registry","group":"sg","why":"Stores and scans container images for the 20 services."}
{"t":"edge","id":"e-ack-acr","from":"ack","to":"acr","label":"pull","kind":"control"}
{"t":"node","id":"arms","product":"arms","label":"ARMS","group":"sg","why":"APM tracing and monitoring for Java microservices."}
{"t":"edge","id":"e-ack-arms","from":"ack","to":"arms","kind":"control"}
{"t":"node","id":"logs","product":"sls","label":"SLS","group":"sg","why":"Centralized log collection and analysis."}
{"t":"edge","id":"e-ack-logs","from":"ack","to":"logs","kind":"control"}
{"t":"ask","id":"db-engine","text":"Which relational engine do your Java services use?","options":["MySQL","PostgreSQL","Oracle-compatible"]}
{"t":"ask","id":"team-size","text":"How large is the team managing this cluster?","options":["Small (1-5 engineers)","Medium (6-20 engineers)","Large (20+ engineers)"]}
{"t":"done","summary":"Kubernetes microservices platform on ACK with MSE Nacos, Cloud-native API Gateway, RocketMQ, Tair and PolarDB in Singapore."}

{"t":"say","text":"I'll draw a data platform that replicates MySQL in real time via DTS, runs nightly batch analytics on MaxCompute, and serves dashboards."}
{"t":"plan","products":["rds","dts","hologres","maxcompute","dataworks","quick-bi","oss"]}
{"t":"assume","id":"source-mysql","text":"Source is an existing RDS MySQL order database","alt":"On-premises or other-cloud MySQL"}
{"t":"assume","id":"region","text":"Singapore region for all workloads","alt":"Another international region"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"Data Platform VPC","parent":"sg"}
{"t":"node","id":"mysql","product":"rds","label":"Order MySQL DB","group":"vpc","zones":["a","b"],"why":"Primary transactional order database to replicate from."}
{"t":"node","id":"dts","product":"dts","label":"DTS Sync","group":"sg","why":"Real-time CDC replication from MySQL to the warehouse."}
{"t":"edge","id":"e-mysql-dts","from":"mysql","to":"dts","label":"CDC","kind":"data"}
{"t":"node","id":"hologres","product":"hologres","label":"Hologres Warehouse","group":"vpc","zones":["a","b"],"why":"Real-time analytical warehouse receiving replicated order data."}
{"t":"edge","id":"e-dts-hologres","from":"dts","to":"hologres","label":"sync","kind":"data"}
{"t":"node","id":"oss","product":"oss","label":"Data Lake Storage","group":"sg","why":"Stores raw extracts and intermediate files for nightly jobs."}
{"t":"edge","id":"e-hologres-oss","from":"hologres","to":"oss","label":"export","kind":"async"}
{"t":"node","id":"maxcompute","product":"maxcompute","label":"MaxCompute Batch","group":"sg","why":"Runs heavy nightly batch analytics over stored data."}
{"t":"edge","id":"e-oss-maxcompute","from":"oss","to":"maxcompute","label":"batch input","kind":"data"}
{"t":"node","id":"dataworks","product":"dataworks","label":"DataWorks Scheduler","group":"sg","why":"Orchestrates nightly ETL pipelines across MaxCompute and Hologres."}
{"t":"edge","id":"e-dataworks-maxcompute","from":"dataworks","to":"maxcompute","label":"schedule","kind":"control"}
{"t":"edge","id":"e-dataworks-hologres","from":"dataworks","to":"hologres","label":"write back","kind":"control"}
{"t":"node","id":"quickbi","product":"quick-bi","label":"Quick BI Dashboards","group":"sg","why":"Business intelligence dashboards for business users."}
{"t":"edge","id":"e-quickbi-hologres","from":"quickbi","to":"hologres","label":"query","kind":"data"}
{"t":"ask","id":"source-location","text":"Where does your source MySQL currently run?","options":["Alibaba Cloud RDS","On-premises data center","Another cloud provider"]}
{"t":"ask","id":"dashboard-users","text":"How many business users will access the dashboards daily?","options":["Under 50","50 to 200","Over 200"]}
{"t":"done","summary":"Real-time MySQL replication via DTS into Hologres, nightly batch on MaxCompute orchestrated by DataWorks, with Quick BI dashboards."}

{"t":"say","text":"I'll connect your on-premises data center to a Singapore VPC over Express Connect and add SMC for step-by-step VM migration."}
{"t":"plan","products":["onprem-dc","express-connect","vpc","ecs","smc"]}
{"t":"assume","id":"link-type","text":"Dedicated private line via Express Connect","alt":"IPsec VPN via VPN Gateway"}
{"t":"group","id":"onprem","kind":"onprem","label":"On-premises DC (Singapore)","parent":null}
{"t":"node","id":"onprem-dc","product":"onprem-dc","label":"On-prem data center","group":"onprem","why":"Existing servers and workloads to migrate."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"node","id":"express-connect","product":"express-connect","label":"Express Connect","group":"sg","why":"Private dedicated link from on-prem to VPC."}
{"t":"edge","id":"e-onprem-express","from":"onprem-dc","to":"express-connect","label":"private link"}
{"t":"group","id":"vpc","kind":"vpc","label":"Migration VPC","parent":"sg"}
{"t":"node","id":"target-vms","product":"ecs","label":"Migrated ECS instances","group":"vpc","zones":["a","b"],"why":"Destination VMs after migration completes."}
{"t":"edge","id":"e-express-vms","from":"express-connect","to":"target-vms","label":"VPC traffic"}
{"t":"node","id":"smc","product":"smc","label":"Server Migration Center","group":"sg","why":"Step-by-step VM migration from on-prem to ECS."}
{"t":"edge","id":"e-smc-onprem","from":"smc","to":"onprem-dc","label":"discover","kind":"control"}
{"t":"edge","id":"e-smc-vms","from":"smc","to":"target-vms","label":"migrate","kind":"control"}
{"t":"ask","id":"migration-scope","text":"How many VMs do you plan to migrate?","options":["Under 50 VMs","50 to 200 VMs","Over 200 VMs"]}
{"t":"ask","id":"bandwidth","text":"What bandwidth does the private link need?","options":["1 Gbps","10 Gbps","Multiple links"]}
{"t":"done","summary":"On-premises data center connected to a Singapore VPC over Express Connect, with Server Migration Center orchestrating VM migration to ECS."}

{"t":"say","text":"I'll draw a real-time IoT telemetry pipeline: devices publish via MQTT, Flink detects anomalies, and DataV powers the live dashboard."}
{"t":"plan","products":["iot-devices","mqtt","kafka","flink","tablestore","tair","sls","datav","smq"]}
{"t":"assume","id":"region","text":"Singapore region for all workloads","alt":"Another international region"}
{"t":"assume","id":"protocol","text":"Devices connect over MQTT","alt":"Direct HTTP or CoAP to IoT Platform"}
{"t":"group","id":"field","kind":"external","label":"Field","parent":null}
{"t":"node","id":"devices","product":"iot-devices","label":"100k IoT devices","group":"field","why":"Sensors publishing telemetry every few seconds."}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc","kind":"vpc","label":"IoT VPC","parent":"sg"}
{"t":"node","id":"mqtt-broker","product":"mqtt","label":"MQTT broker","group":"vpc","zones":["a","b"],"why":"Ingests high-frequency telemetry from 100k devices."}
{"t":"edge","id":"e-devices-mqtt","from":"devices","to":"mqtt-broker","label":"telemetry","kind":"data"}
{"t":"node","id":"kafka","product":"kafka","label":"Kafka cluster","group":"vpc","zones":["a","b"],"why":"Buffers the high-throughput device stream for processing."}
{"t":"edge","id":"e-mqtt-kafka","from":"mqtt-broker","to":"kafka","label":"stream","kind":"async"}
{"t":"node","id":"flink","product":"flink","label":"Flink jobs","group":"vpc","zones":["a","b"],"why":"Runs real-time SQL to detect anomalies in telemetry."}
{"t":"edge","id":"e-kafka-flink","from":"kafka","to":"flink","label":"consume","kind":"data"}
{"t":"node","id":"queue","product":"smq","label":"Alert queue","group":"sg","why":"Decouples anomaly alerts for downstream consumers."}
{"t":"edge","id":"e-flink-queue","from":"flink","to":"queue","label":"alerts","kind":"async"}
{"t":"node","id":"tsdb","product":"tablestore","label":"Telemetry store","group":"sg","why":"Stores time-series telemetry at massive scale cheaply."}
{"t":"edge","id":"e-flink-tsdb","from":"flink","to":"tsdb","label":"write","kind":"data"}
{"t":"node","id":"cache","product":"tair","label":"Live state cache","group":"vpc","zones":["a","b"],"why":"Holds latest device states for fast dashboard reads."}
{"t":"edge","id":"e-flink-cache","from":"flink","to":"cache","label":"state","kind":"data"}
{"t":"node","id":"logs","product":"sls","label":"Log Service","group":"sg","why":"Collects pipeline logs and triggers alert notifications."}
{"t":"edge","id":"e-flink-logs","from":"flink","to":"logs","label":"logs","kind":"control"}
{"t":"edge","id":"e-queue-logs","from":"queue","to":"logs","label":"notify","kind":"async"}
{"t":"node","id":"dashboard","product":"datav","label":"DataV dashboard","group":"sg","why":"Renders the live operations dashboard for operators."}
{"t":"edge","id":"e-dashboard-cache","from":"dashboard","to":"cache","label":"read","kind":"data"}
{"t":"edge","id":"e-dashboard-tsdb","from":"dashboard","to":"tsdb","label":"history","kind":"data"}
{"t":"ask","id":"alert-channel","text":"How should anomaly alerts be delivered to your team?","options":["SMS","Email","DingTalk webhook","Custom app push"]}
{"t":"ask","id":"device-protocol","text":"Do devices already use MQTT, or do you need HTTP/CoAP?","options":["MQTT","HTTP","CoAP"]}
{"t":"done","summary":"Real-time IoT pipeline: 100k devices via MQTT into Kafka, Flink for anomaly detection, Tablestore for storage, Tair for live state, SMQ for alerts, and DataV for the dashboard."}

{"t":"say","text":"For 25 developers needing an agentic coding assistant with SSO and admin controls, Qoder Teams is the right fit."}
{"t":"rec","product":"qoder-teams","fit":"primary","why":"Agentic coding platform for teams with SSO, privacy mode, admin dashboard and usage analytics."}
{"t":"rec","product":"model-studio","fit":"complement","why":"Provides the Qwen model APIs that power Qoder agents."}
{"t":"done","summary":"Qoder Teams gives your 25 developers an agentic AI coding assistant with built-in SSO and admin controls."}

{"t":"say","text":"I'll draw a multi-region SaaS with Global Accelerator for low latency worldwide and GTM for automatic DNS failover."}
{"t":"plan","products":["users","dns","gtm","ga","alb","waf","ecs","rds","tair","oss","sls"]}
{"t":"assume","id":"scale","text":"About 10k users globally","alt":"Over 100k users"}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Global users","group":"internet","why":"Users in Asia, Europe and the US accessing the SaaS."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Authoritative DNS resolving the domain to GTM."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"node","id":"gtm","product":"gtm","label":"GTM","group":null,"why":"Health checks and automatic failover between regions."}
{"t":"edge","id":"e-dns-gtm","from":"dns","to":"gtm","kind":"resolve"}
{"t":"node","id":"ga","product":"ga","label":"Global Accelerator","group":null,"why":"Anycast entry points routing traffic over Alibaba backbone."}
{"t":"edge","id":"e-users-ga","from":"users","to":"ga","label":"HTTPS"}
{"t":"group","id":"sg","kind":"region","label":"Singapore (ap-southeast-1)","parent":null}
{"t":"group","id":"vpc-sg","kind":"vpc","label":"Primary VPC","parent":"sg"}
{"t":"node","id":"alb-sg","product":"alb","label":"ALB primary","group":"vpc-sg","zones":["a","b"],"why":"Load balances app servers in the primary region."}
{"t":"node","id":"waf-sg","product":"waf","label":"WAF","group":"vpc-sg","attachTo":"alb-sg","why":"Blocks attacks before reaching the app."}
{"t":"edge","id":"e-ga-alb-sg","from":"ga","to":"alb-sg","label":"primary"}
{"t":"node","id":"app-sg","product":"ecs","label":"App servers","group":"vpc-sg","zones":["a","b"],"why":"Runs the SaaS application across two zones."}
{"t":"edge","id":"e-alb-sg-app-sg","from":"alb-sg","to":"app-sg"}
{"t":"node","id":"cache-sg","product":"tair","label":"Session cache","group":"vpc-sg","zones":["a","b"],"why":"Keeps sessions fast in the primary region."}
{"t":"node","id":"db-sg","product":"rds","label":"Primary DB","group":"vpc-sg","zones":["a","b"],"why":"Stores SaaS data with zone-level HA."}
{"t":"edge","id":"e-app-sg-cache-sg","from":"app-sg","to":"cache-sg"}
{"t":"edge","id":"e-app-sg-db-sg","from":"app-sg","to":"db-sg","label":"SQL"}
{"t":"group","id":"ff","kind":"region","label":"Frankfurt (eu-central-1)","parent":null}
{"t":"group","id":"vpc-ff","kind":"vpc","label":"Failover VPC","parent":"ff"}
{"t":"node","id":"alb-ff","product":"alb","label":"ALB failover","group":"vpc-ff","zones":["a","b"],"why":"Load balances app servers in the failover region."}
{"t":"edge","id":"e-ga-alb-ff","from":"ga","to":"alb-ff","label":"failover"}
{"t":"node","id":"app-ff","product":"ecs","label":"App servers","group":"vpc-ff","zones":["a","b"],"why":"Standby compute for automatic failover."}
